public class ViewCountProcessor {

    public static void main(String[] args) {
        StreamsBuilder builder = new StreamsBuilder();

        KStream<String, String> viewEvents = builder.stream("view-events");

        KTable<String, Long> viewCounts = viewEvents
            .groupBy((key, value) -> extractVideoId(value))
            .count(Materialized.as("view-counts-store"));

        viewCounts
            .toStream()
            .to("view-counts-output", Produced.with(Serdes.String(), Serdes.Long()));

        KafkaStreams streams = new KafkaStreams(builder.build(), streamsConfig());
        streams.start();

        Runtime.getRuntime().addShutdownHook(new Thread(streams::close));
    }

    private static String extractVideoId(String eventJson) {
        // parse the event payload and pull out the videoId field
        return JsonUtil.parse(eventJson).get("videoId").asText();
    }
}

